-- PART 03: 보유종목, 정기매수, 계좌별 대기현금 및 현금이력

-- TB_HOLD: 기존 102건과 레거시 업무키를 보존하면서 ID 기반 구조로 전환한다.
DROP VIEW tb_hold;
ALTER TABLE "TB_HOLD" RENAME COLUMN "QTY" TO "HOLD_QTY";
ALTER TABLE "TB_HOLD"
  ADD COLUMN "HOLD_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  ADD COLUMN "STK_ID" BIGINT,
  ADD COLUMN "CUR_PRC" NUMERIC(20,6), ADD COLUMN "EXCH_RT" NUMERIC(20,6) DEFAULT 1,
  ADD COLUMN "ORG_EVL_AMT" NUMERIC(20,4), ADD COLUMN "EVL_AMT" NUMERIC(20,4),
  ADD COLUMN "ORG_PL_AMT" NUMERIC(20,4), ADD COLUMN "PL_AMT" NUMERIC(20,4), ADD COLUMN "PL_RT" NUMERIC(10,4),
  ADD COLUMN "TGT_WGT" NUMERIC(7,4), ADD COLUMN "CUR_WGT" NUMERIC(7,4), ADD COLUMN "WGT_DIFF_RT" NUMERIC(10,4),
  ADD COLUMN "WGT_STS" VARCHAR(20), ADD COLUMN "RISK_GRADE" VARCHAR(20), ADD COLUMN "HOLD_STS" VARCHAR(20) DEFAULT 'ACTIVE',
  ADD COLUMN "PRC_BASE_DT" DATE, ADD COLUMN "CALC_DTTM" TIMESTAMP WITH TIME ZONE, ADD COLUMN "MEMO" VARCHAR(1000),
  ADD COLUMN "USE_YN" CHAR(1) DEFAULT 'Y', ADD COLUMN "DEL_YN" CHAR(1) DEFAULT 'N',
  ADD COLUMN "CRT_DTTM" TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP, ADD COLUMN "CRT_USR_ID" VARCHAR(50),
  ADD COLUMN "UPD_DTTM" TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP, ADD COLUMN "UPD_USR_ID" VARCHAR(50);
UPDATE "TB_HOLD" h SET "STK_ID"=s."STK_ID", "CRT_DTTM"=h."REG_DT" AT TIME ZONE 'Asia/Seoul',
  "UPD_DTTM"=h."MOD_DT" AT TIME ZONE 'Asia/Seoul', "CRT_USR_ID"='SYSTEM', "UPD_USR_ID"='SYSTEM'
FROM "TB_STK" s WHERE s."MKT_CD"=h."MKT_CD" AND s."STK_CD"=h."STK_CD";
UPDATE "TB_HOLD" h SET "CUR_PRC"=p."CLS_PRC", "PRC_BASE_DT"=p."TRD_DT"
FROM (SELECT DISTINCT ON ("MKT_CD","STK_CD") "MKT_CD","STK_CD","CLS_PRC","TRD_DT" FROM "TB_PRC_DAY" ORDER BY "MKT_CD","STK_CD","TRD_DT" DESC) p
WHERE p."MKT_CD"=h."MKT_CD" AND p."STK_CD"=h."STK_CD";
UPDATE "TB_HOLD" h SET "TGT_WGT"=CASE WHEN ss."TGT_WGT"<=1 THEN ss."TGT_WGT"*100 ELSE ss."TGT_WGT" END
FROM "TB_STK_SET" ss WHERE ss."ACCT_TP"=h."ACCT_TP" AND ss."MKT_CD"=h."MKT_CD" AND ss."STK_CD"=h."STK_CD";
UPDATE "TB_HOLD" SET "ORG_EVL_AMT"="HOLD_QTY"*"CUR_PRC", "EVL_AMT"="HOLD_QTY"*"CUR_PRC"*"EXCH_RT",
 "ORG_PL_AMT"=("CUR_PRC"-"AVG_PRC")*"HOLD_QTY", "PL_AMT"=("CUR_PRC"-"AVG_PRC")*"HOLD_QTY"*"EXCH_RT",
 "PL_RT"=CASE WHEN "AVG_PRC">0 THEN (("CUR_PRC"-"AVG_PRC")/"AVG_PRC")*100 END, "CALC_DTTM"=CURRENT_TIMESTAMP
WHERE "CUR_PRC" IS NOT NULL;
ALTER TABLE "TB_STK_SET" DROP CONSTRAINT "FK_STK_SET_01";
ALTER TABLE "TB_ANALYSIS" DROP CONSTRAINT "FK_ANALYSIS_01";
ALTER TABLE "TB_HOLD" DROP CONSTRAINT "PK_ACCT_STK";
ALTER TABLE "TB_HOLD" RENAME CONSTRAINT "FK_TB_HOLD_ACCT" TO "FK_TB_HOLD_01";
ALTER TABLE "TB_HOLD"
 ALTER COLUMN "ACCT_ID" SET NOT NULL, ALTER COLUMN "STK_ID" SET NOT NULL,
 ALTER COLUMN "HOLD_QTY" TYPE NUMERIC(20,8), ALTER COLUMN "HOLD_QTY" SET NOT NULL, ALTER COLUMN "HOLD_QTY" SET DEFAULT 0,
 ALTER COLUMN "AVG_PRC" TYPE NUMERIC(20,6), ALTER COLUMN "AVG_PRC" SET NOT NULL, ALTER COLUMN "AVG_PRC" SET DEFAULT 0,
 ALTER COLUMN "EXCH_RT" SET NOT NULL, ALTER COLUMN "HOLD_STS" SET NOT NULL, ALTER COLUMN "USE_YN" SET NOT NULL,
 ALTER COLUMN "DEL_YN" SET NOT NULL, ALTER COLUMN "CRT_DTTM" SET NOT NULL, ALTER COLUMN "UPD_DTTM" SET NOT NULL,
 ADD CONSTRAINT "PK_TB_HOLD" PRIMARY KEY ("HOLD_ID"), ADD CONSTRAINT "UK_TB_HOLD_01" UNIQUE ("ACCT_ID","STK_ID"),
 ADD CONSTRAINT "UK_TB_HOLD_LEGACY" UNIQUE ("ACCT_TP","MKT_CD","STK_CD"),
 ADD CONSTRAINT "FK_TB_HOLD_02" FOREIGN KEY ("STK_ID") REFERENCES "TB_STK"("STK_ID"),
 ADD CONSTRAINT "CK_TB_HOLD_01" CHECK ("HOLD_QTY">=0), ADD CONSTRAINT "CK_TB_HOLD_02" CHECK ("AVG_PRC">=0),
 ADD CONSTRAINT "CK_TB_HOLD_03" CHECK ("CUR_PRC" IS NULL OR "CUR_PRC">=0), ADD CONSTRAINT "CK_TB_HOLD_04" CHECK ("EXCH_RT">0),
 ADD CONSTRAINT "CK_TB_HOLD_05" CHECK ("TGT_WGT" IS NULL OR "TGT_WGT" BETWEEN 0 AND 100),
 ADD CONSTRAINT "CK_TB_HOLD_06" CHECK ("CUR_WGT" IS NULL OR "CUR_WGT" BETWEEN 0 AND 100),
 ADD CONSTRAINT "CK_TB_HOLD_07" CHECK ("WGT_STS" IS NULL OR "WGT_STS" IN ('UNDERWEIGHT','NORMAL','OVERWEIGHT')),
 ADD CONSTRAINT "CK_TB_HOLD_08" CHECK ("HOLD_STS" IN ('ACTIVE','CLOSED','TRANSFER_PENDING')),
 ADD CONSTRAINT "CK_TB_HOLD_09" CHECK ("USE_YN" IN ('Y','N')), ADD CONSTRAINT "CK_TB_HOLD_10" CHECK ("DEL_YN" IN ('Y','N'));
ALTER TABLE "TB_STK_SET" ADD CONSTRAINT "FK_STK_SET_01" FOREIGN KEY ("ACCT_TP","MKT_CD","STK_CD") REFERENCES "TB_HOLD"("ACCT_TP","MKT_CD","STK_CD") ON DELETE CASCADE;
ALTER TABLE "TB_ANALYSIS" ADD CONSTRAINT "FK_ANALYSIS_01" FOREIGN KEY ("ACCT_TP","MKT_CD","STK_CD") REFERENCES "TB_HOLD"("ACCT_TP","MKT_CD","STK_CD") ON DELETE CASCADE;
CREATE INDEX "IDX_TB_HOLD_01" ON "TB_HOLD"("ACCT_ID"); CREATE INDEX "IDX_TB_HOLD_02" ON "TB_HOLD"("STK_ID");
CREATE INDEX "IDX_TB_HOLD_03" ON "TB_HOLD"("WGT_STS"); CREATE INDEX "IDX_TB_HOLD_04" ON "TB_HOLD"("RISK_GRADE");
CREATE INDEX "IDX_TB_HOLD_05" ON "TB_HOLD"("USE_YN","DEL_YN");
CREATE VIEW tb_hold AS SELECT h."ACCT_TP" AS market_scope,h."STK_CD" AS stock_code,s."STK_NM" AS stock_name,
 s."LIST_SCOPE" AS listing_scope,s."ASSET_TP" AS asset_type,s."EXCH_NM" AS exchange_name,s."CURR" AS currency,
 s."PRVDR" AS provider,s."ACTV_YN" AS active_yn,h."REG_DT" AS created_at,h."MOD_DT" AS updated_at,
 h."HOLD_QTY" AS qty,h."AVG_PRC" AS avg_prc FROM "TB_HOLD" h JOIN "TB_STK" s ON s."STK_ID"=h."STK_ID";
COMMENT ON TABLE "TB_HOLD" IS '계좌별 보유종목';
COMMENT ON COLUMN "TB_HOLD"."HOLD_ID" IS '보유종목 ID'; COMMENT ON COLUMN "TB_HOLD"."ACCT_ID" IS '계좌 ID'; COMMENT ON COLUMN "TB_HOLD"."STK_ID" IS '종목 ID';
COMMENT ON COLUMN "TB_HOLD"."HOLD_QTY" IS '보유수량'; COMMENT ON COLUMN "TB_HOLD"."AVG_PRC" IS '평단가(거래통화 기준)'; COMMENT ON COLUMN "TB_HOLD"."CUR_PRC" IS '현재가(거래통화 기준)';
COMMENT ON COLUMN "TB_HOLD"."EXCH_RT" IS '원화 환산 적용 환율'; COMMENT ON COLUMN "TB_HOLD"."ORG_EVL_AMT" IS '원통화 평가금액'; COMMENT ON COLUMN "TB_HOLD"."EVL_AMT" IS '원화 환산 평가금액';
COMMENT ON COLUMN "TB_HOLD"."ORG_PL_AMT" IS '원통화 평가손익금액'; COMMENT ON COLUMN "TB_HOLD"."PL_AMT" IS '원화 환산 평가손익금액'; COMMENT ON COLUMN "TB_HOLD"."PL_RT" IS '평가손익률';
COMMENT ON COLUMN "TB_HOLD"."TGT_WGT" IS '계좌 내 종목 목표비중(0~100)'; COMMENT ON COLUMN "TB_HOLD"."CUR_WGT" IS '계좌 내 종목 현재비중(0~100)'; COMMENT ON COLUMN "TB_HOLD"."WGT_DIFF_RT" IS '현재비중과 목표비중의 차이';
COMMENT ON COLUMN "TB_HOLD"."WGT_STS" IS '비중상태(UNDERWEIGHT, NORMAL, OVERWEIGHT)'; COMMENT ON COLUMN "TB_HOLD"."RISK_GRADE" IS '종목 위험등급'; COMMENT ON COLUMN "TB_HOLD"."HOLD_STS" IS '보유상태(ACTIVE, CLOSED, TRANSFER_PENDING)';
COMMENT ON COLUMN "TB_HOLD"."PRC_BASE_DT" IS '현재가 기준일'; COMMENT ON COLUMN "TB_HOLD"."CALC_DTTM" IS '평가금액 및 비중 계산일시'; COMMENT ON COLUMN "TB_HOLD"."MEMO" IS '보유종목 메모';
COMMENT ON COLUMN "TB_HOLD"."USE_YN" IS '사용 여부(Y:사용, N:미사용)'; COMMENT ON COLUMN "TB_HOLD"."DEL_YN" IS '삭제 여부(Y:삭제, N:정상)'; COMMENT ON COLUMN "TB_HOLD"."CRT_DTTM" IS '생성일시'; COMMENT ON COLUMN "TB_HOLD"."CRT_USR_ID" IS '생성자 ID'; COMMENT ON COLUMN "TB_HOLD"."UPD_DTTM" IS '수정일시'; COMMENT ON COLUMN "TB_HOLD"."UPD_USR_ID" IS '수정자 ID';

-- TB_REG_BUY: 기존 88건을 문서 구조로 확장한다.
DROP VIEW tb_reg_buy;
ALTER TABLE "TB_REG_BUY" RENAME COLUMN "SET_ID" TO "REG_BUY_ID";
ALTER TABLE "TB_REG_BUY"
 ADD COLUMN "ACCT_ID" BIGINT, ADD COLUMN "STK_ID" BIGINT, ADD COLUMN "BUY_CYCLE" VARCHAR(20),
 ADD COLUMN "BUY_DAY_CD" VARCHAR(20), ADD COLUMN "BUY_DAY_NO" INTEGER, ADD COLUMN "MIN_BUY_AMT" NUMERIC(20,4) DEFAULT 0,
 ADD COLUMN "MAX_BUY_AMT" NUMERIC(20,4), ADD COLUMN "MAX_MULT" NUMERIC(8,4) DEFAULT 3,
 ADD COLUMN "MKT_MULT" NUMERIC(8,4), ADD COLUMN "STK_ADJ_MULT" NUMERIC(8,4), ADD COLUMN "WGT_ADJ_MULT" NUMERIC(8,4),
 ADD COLUMN "RISK_ADJ_MULT" NUMERIC(8,4), ADD COLUMN "FINAL_MULT" NUMERIC(8,4), ADD COLUMN "BASE_BUY_AMT" NUMERIC(20,4),
 ADD COLUMN "RCMD_BUY_AMT" NUMERIC(20,4), ADD COLUMN "SAVED_AMT" NUMERIC(20,4), ADD COLUMN "ACT_SIG" VARCHAR(30),
 ADD COLUMN "BUY_STS" VARCHAR(20) DEFAULT 'ACTIVE', ADD COLUMN "USER_PAUSE_YN" CHAR(1) DEFAULT 'N',
 ADD COLUMN "AUTO_CALC_YN" CHAR(1) DEFAULT 'Y', ADD COLUMN "LAST_CALC_DT" DATE, ADD COLUMN "RULE_VER_NO" INTEGER DEFAULT 1,
 ADD COLUMN "USE_YN" CHAR(1) DEFAULT 'Y', ADD COLUMN "DEL_YN" CHAR(1) DEFAULT 'N',
 ADD COLUMN "CRT_DTTM" TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP, ADD COLUMN "CRT_USR_ID" VARCHAR(50),
 ADD COLUMN "UPD_DTTM" TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP, ADD COLUMN "UPD_USR_ID" VARCHAR(50);
UPDATE "TB_REG_BUY" r SET "ACCT_ID"=a."ACCT_ID","STK_ID"=s."STK_ID",
 "BUY_CYCLE"=CASE WHEN COALESCE(r."BASE_CYCLE_TP",r."CYCLE_TP") IN ('DAILY','WEEKLY','MONTHLY') THEN COALESCE(r."BASE_CYCLE_TP",r."CYCLE_TP") ELSE 'CUSTOM' END,
 "BUY_DAY_CD"=CASE WHEN COALESCE(r."BASE_WEEK_DAY",r."WEEK_DAY") IN ('MON','TUE','WED','THU','FRI') THEN COALESCE(r."BASE_WEEK_DAY",r."WEEK_DAY") END,
 "BUY_DAY_NO"=COALESCE(r."BASE_MONTH_DAY",r."MONTH_DAY"), "MIN_BUY_AMT"=COALESCE(r."BASE_AMT",r."AMT",0),
 "MAX_BUY_AMT"=COALESCE(r."BASE_AMT",r."AMT",0)*3, "BASE_BUY_AMT"=COALESCE(r."BASE_AMT",r."AMT",0),
 "BUY_STS"=CASE WHEN r."CYCLE_TP"='PAUSED' OR r."EXEC_ST"='PAUSED' OR r."ACTV_YN"='N' THEN 'PAUSED' ELSE 'ACTIVE' END,
 "USER_PAUSE_YN"=CASE WHEN r."CYCLE_TP"='PAUSED' THEN 'Y' ELSE 'N' END, "USE_YN"=r."ACTV_YN", "DEL_YN"='N',
 "CRT_DTTM"=COALESCE(r."REG_DT",CURRENT_TIMESTAMP) AT TIME ZONE 'Asia/Seoul', "UPD_DTTM"=COALESCE(r."MOD_DT",CURRENT_TIMESTAMP) AT TIME ZONE 'Asia/Seoul',
 "CRT_USR_ID"='SYSTEM',"UPD_USR_ID"='SYSTEM'
FROM "TB_ACCT" a,"TB_STK" s WHERE a."ACCT_TP"=r."ACCT_TP" AND s."MKT_CD"=r."MKT_CD" AND s."STK_CD"=r."STK_CD";
ALTER TABLE "TB_REG_BUY" DROP CONSTRAINT "tb_regular_investment_setting_pkey";
ALTER TABLE "TB_REG_BUY"
 ALTER COLUMN "ACCT_ID" SET NOT NULL, ALTER COLUMN "STK_ID" SET NOT NULL, ALTER COLUMN "BUY_CYCLE" SET NOT NULL,
 ALTER COLUMN "MIN_BUY_AMT" SET NOT NULL, ALTER COLUMN "MAX_MULT" SET NOT NULL, ALTER COLUMN "BUY_STS" SET NOT NULL,
 ALTER COLUMN "USER_PAUSE_YN" SET NOT NULL, ALTER COLUMN "AUTO_CALC_YN" SET NOT NULL, ALTER COLUMN "RULE_VER_NO" SET NOT NULL,
 ALTER COLUMN "USE_YN" SET NOT NULL, ALTER COLUMN "DEL_YN" SET NOT NULL, ALTER COLUMN "CRT_DTTM" SET NOT NULL, ALTER COLUMN "UPD_DTTM" SET NOT NULL,
 ALTER COLUMN "PAUSE_RSN" TYPE VARCHAR(500),
 ADD CONSTRAINT "PK_TB_REG_BUY" PRIMARY KEY ("REG_BUY_ID"), ADD CONSTRAINT "UK_TB_REG_BUY_01" UNIQUE ("ACCT_ID","STK_ID"),
 ADD CONSTRAINT "FK_TB_REG_BUY_01" FOREIGN KEY ("ACCT_ID") REFERENCES "TB_ACCT"("ACCT_ID"), ADD CONSTRAINT "FK_TB_REG_BUY_02" FOREIGN KEY ("STK_ID") REFERENCES "TB_STK"("STK_ID"),
 ADD CONSTRAINT "CK_TB_REG_BUY_01" CHECK ("BUY_CYCLE" IN ('DAILY','WEEKLY','MONTHLY','CUSTOM')),
 ADD CONSTRAINT "CK_TB_REG_BUY_02" CHECK ("BUY_DAY_CD" IS NULL OR "BUY_DAY_CD" IN ('MON','TUE','WED','THU','FRI')),
 ADD CONSTRAINT "CK_TB_REG_BUY_03" CHECK ("BUY_DAY_NO" IS NULL OR "BUY_DAY_NO" BETWEEN 1 AND 31),
 ADD CONSTRAINT "CK_TB_REG_BUY_04" CHECK ("MIN_BUY_AMT">=0), ADD CONSTRAINT "CK_TB_REG_BUY_05" CHECK ("MAX_BUY_AMT" IS NULL OR "MAX_BUY_AMT">="MIN_BUY_AMT"),
 ADD CONSTRAINT "CK_TB_REG_BUY_06" CHECK ("MAX_MULT">=0), ADD CONSTRAINT "CK_TB_REG_BUY_07" CHECK ("FINAL_MULT" IS NULL OR "FINAL_MULT">=0),
 ADD CONSTRAINT "CK_TB_REG_BUY_08" CHECK ("RCMD_BUY_AMT" IS NULL OR "RCMD_BUY_AMT">=0), ADD CONSTRAINT "CK_TB_REG_BUY_09" CHECK ("SAVED_AMT" IS NULL OR "SAVED_AMT">=0),
 ADD CONSTRAINT "CK_TB_REG_BUY_10" CHECK ("ACT_SIG" IS NULL OR "ACT_SIG" IN ('PAUSE','REDUCE','KEEP_MINIMUM','INCREASE','ADDITIONAL_BUY','REBUY')),
 ADD CONSTRAINT "CK_TB_REG_BUY_11" CHECK ("BUY_STS" IN ('ACTIVE','PAUSED','STOPPED')), ADD CONSTRAINT "CK_TB_REG_BUY_12" CHECK ("USER_PAUSE_YN" IN ('Y','N')),
 ADD CONSTRAINT "CK_TB_REG_BUY_13" CHECK ("AUTO_CALC_YN" IN ('Y','N')), ADD CONSTRAINT "CK_TB_REG_BUY_14" CHECK ("USE_YN" IN ('Y','N')), ADD CONSTRAINT "CK_TB_REG_BUY_15" CHECK ("DEL_YN" IN ('Y','N'));
CREATE INDEX "IDX_TB_REG_BUY_01" ON "TB_REG_BUY"("ACCT_ID"); CREATE INDEX "IDX_TB_REG_BUY_02" ON "TB_REG_BUY"("STK_ID");
CREATE INDEX "IDX_TB_REG_BUY_03" ON "TB_REG_BUY"("BUY_STS","USE_YN","DEL_YN"); CREATE INDEX "IDX_TB_REG_BUY_04" ON "TB_REG_BUY"("LAST_CALC_DT");
CREATE VIEW tb_reg_buy AS SELECT "REG_BUY_ID" AS setting_id,"ACCT_TP" AS account_type,"STK_CD" AS stock_code,"STK_NM" AS stock_name,
 "CYCLE_TP" AS cycle_type,"WEEK_DAY" AS day_of_week,"MONTH_DAY" AS day_of_month,"AMT" AS amount,"QTY" AS quantity,
 "ACTV_YN" AS active_yn,"PAUSE_RSN" AS pause_reason,"START_DT" AS start_date,"END_DT" AS end_date,"REG_DT" AS created_at,"MOD_DT" AS updated_at
FROM "TB_REG_BUY";
COMMENT ON TABLE "TB_REG_BUY" IS '계좌별 종목 정기매수 설정';
COMMENT ON COLUMN "TB_REG_BUY"."REG_BUY_ID" IS '정기매수 설정 ID'; COMMENT ON COLUMN "TB_REG_BUY"."ACCT_ID" IS '계좌 ID'; COMMENT ON COLUMN "TB_REG_BUY"."STK_ID" IS '종목 ID';
COMMENT ON COLUMN "TB_REG_BUY"."BUY_CYCLE" IS '매수주기(DAILY, WEEKLY, MONTHLY, CUSTOM)'; COMMENT ON COLUMN "TB_REG_BUY"."BUY_DAY_CD" IS '매수요일 코드(MON~FRI)'; COMMENT ON COLUMN "TB_REG_BUY"."BUY_DAY_NO" IS '월 정기매수일(1~31)';
COMMENT ON COLUMN "TB_REG_BUY"."MIN_BUY_AMT" IS '종목별 최소 매수금액'; COMMENT ON COLUMN "TB_REG_BUY"."MAX_BUY_AMT" IS '종목별 최대 매수금액'; COMMENT ON COLUMN "TB_REG_BUY"."MAX_MULT" IS '허용 최대 매수배수';
COMMENT ON COLUMN "TB_REG_BUY"."MKT_MULT" IS '시장국면 기본 매수배수'; COMMENT ON COLUMN "TB_REG_BUY"."STK_ADJ_MULT" IS '종목 펀더멘털 및 낙폭 보정배수'; COMMENT ON COLUMN "TB_REG_BUY"."WGT_ADJ_MULT" IS '목표비중 대비 현재비중 보정배수';
COMMENT ON COLUMN "TB_REG_BUY"."RISK_ADJ_MULT" IS '위험도 보정배수'; COMMENT ON COLUMN "TB_REG_BUY"."FINAL_MULT" IS '최종 적용 매수배수'; COMMENT ON COLUMN "TB_REG_BUY"."BASE_BUY_AMT" IS '감액 계산 전 기준 예정 매수금액';
COMMENT ON COLUMN "TB_REG_BUY"."RCMD_BUY_AMT" IS '최종 추천 정기매수금액'; COMMENT ON COLUMN "TB_REG_BUY"."SAVED_AMT" IS '정기매수 감액 또는 중단으로 확보한 금액'; COMMENT ON COLUMN "TB_REG_BUY"."ACT_SIG" IS '행동신호';
COMMENT ON COLUMN "TB_REG_BUY"."BUY_STS" IS '정기매수 상태(ACTIVE, PAUSED, STOPPED)'; COMMENT ON COLUMN "TB_REG_BUY"."PAUSE_RSN" IS '정기매수 일시정지 또는 중단 사유'; COMMENT ON COLUMN "TB_REG_BUY"."USER_PAUSE_YN" IS '사용자 직접 일시정지 여부';
COMMENT ON COLUMN "TB_REG_BUY"."AUTO_CALC_YN" IS '자동 계산 적용 여부'; COMMENT ON COLUMN "TB_REG_BUY"."LAST_CALC_DT" IS '마지막 추천금액 계산 기준일'; COMMENT ON COLUMN "TB_REG_BUY"."RULE_VER_NO" IS '적용 계산규칙 버전';
COMMENT ON COLUMN "TB_REG_BUY"."USE_YN" IS '사용 여부(Y:사용, N:미사용)'; COMMENT ON COLUMN "TB_REG_BUY"."DEL_YN" IS '삭제 여부(Y:삭제, N:정상)'; COMMENT ON COLUMN "TB_REG_BUY"."CRT_DTTM" IS '생성일시'; COMMENT ON COLUMN "TB_REG_BUY"."CRT_USR_ID" IS '생성자 ID'; COMMENT ON COLUMN "TB_REG_BUY"."UPD_DTTM" IS '수정일시'; COMMENT ON COLUMN "TB_REG_BUY"."UPD_USR_ID" IS '수정자 ID';

CREATE TABLE "TB_CASH_RSV" (
 "CASH_RSV_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY, "ACCT_ID" BIGINT NOT NULL,
 "RSV_AMT" NUMERIC(20,4) NOT NULL DEFAULT 0, "ACCUM_AMT" NUMERIC(20,4) NOT NULL DEFAULT 0, "USED_AMT" NUMERIC(20,4) NOT NULL DEFAULT 0,
 "LAST_TX_DT" DATE, "VER_NO" BIGINT NOT NULL DEFAULT 0, "CRT_DTTM" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
 "CRT_USR_ID" VARCHAR(50), "UPD_DTTM" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, "UPD_USR_ID" VARCHAR(50),
 CONSTRAINT "PK_TB_CASH_RSV" PRIMARY KEY("CASH_RSV_ID"), CONSTRAINT "UK_TB_CASH_RSV_01" UNIQUE("ACCT_ID"),
 CONSTRAINT "FK_TB_CASH_RSV_01" FOREIGN KEY("ACCT_ID") REFERENCES "TB_ACCT"("ACCT_ID"),
 CONSTRAINT "CK_TB_CASH_RSV_01" CHECK("RSV_AMT">=0), CONSTRAINT "CK_TB_CASH_RSV_02" CHECK("ACCUM_AMT">=0), CONSTRAINT "CK_TB_CASH_RSV_03" CHECK("USED_AMT">=0));
CREATE INDEX "IDX_TB_CASH_RSV_01" ON "TB_CASH_RSV"("ACCT_ID");
INSERT INTO "TB_CASH_RSV"("ACCT_ID","RSV_AMT","ACCUM_AMT","CRT_USR_ID","UPD_USR_ID") SELECT "ACCT_ID","RSV_CASH_AMT","RSV_CASH_AMT",'SYSTEM','SYSTEM' FROM "TB_ACCT";
COMMENT ON TABLE "TB_CASH_RSV" IS '계좌별 추가매수 대기현금 잔액'; COMMENT ON COLUMN "TB_CASH_RSV"."CASH_RSV_ID" IS '대기현금 ID'; COMMENT ON COLUMN "TB_CASH_RSV"."ACCT_ID" IS '계좌 ID';
COMMENT ON COLUMN "TB_CASH_RSV"."RSV_AMT" IS '현재 추가매수 대기현금 잔액'; COMMENT ON COLUMN "TB_CASH_RSV"."ACCUM_AMT" IS '누적 대기현금 적립금액'; COMMENT ON COLUMN "TB_CASH_RSV"."USED_AMT" IS '누적 대기현금 사용금액';
COMMENT ON COLUMN "TB_CASH_RSV"."LAST_TX_DT" IS '마지막 대기현금 거래일'; COMMENT ON COLUMN "TB_CASH_RSV"."VER_NO" IS '낙관적 잠금 버전'; COMMENT ON COLUMN "TB_CASH_RSV"."CRT_DTTM" IS '생성일시'; COMMENT ON COLUMN "TB_CASH_RSV"."CRT_USR_ID" IS '생성자 ID'; COMMENT ON COLUMN "TB_CASH_RSV"."UPD_DTTM" IS '수정일시'; COMMENT ON COLUMN "TB_CASH_RSV"."UPD_USR_ID" IS '수정자 ID';

CREATE TABLE "TB_CASH_HIS" (
 "CASH_HIS_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY,"ACCT_ID" BIGINT NOT NULL,"REG_BUY_ID" BIGINT,"TX_DT" DATE NOT NULL,
 "CASH_TP" VARCHAR(20) NOT NULL,"TX_TP" VARCHAR(30) NOT NULL,"IN_OUT_TP" VARCHAR(10) NOT NULL,"TX_AMT" NUMERIC(20,4) NOT NULL,
 "BAL_BFR_AMT" NUMERIC(20,4) NOT NULL,"BAL_AFT_AMT" NUMERIC(20,4) NOT NULL,"IDEMP_KEY" VARCHAR(100) NOT NULL,
 "REF_TBL_NM" VARCHAR(50),"REF_ID" BIGINT,"TX_RSN" VARCHAR(500),"CRT_DTTM" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,"CRT_USR_ID" VARCHAR(50),
 CONSTRAINT "PK_TB_CASH_HIS" PRIMARY KEY("CASH_HIS_ID"),CONSTRAINT "UK_TB_CASH_HIS_01" UNIQUE("IDEMP_KEY"),
 CONSTRAINT "FK_TB_CASH_HIS_01" FOREIGN KEY("ACCT_ID") REFERENCES "TB_ACCT"("ACCT_ID"),CONSTRAINT "FK_TB_CASH_HIS_02" FOREIGN KEY("REG_BUY_ID") REFERENCES "TB_REG_BUY"("REG_BUY_ID"),
 CONSTRAINT "CK_TB_CASH_HIS_01" CHECK("CASH_TP" IN ('NORMAL','RESERVE')),
 CONSTRAINT "CK_TB_CASH_HIS_02" CHECK("TX_TP" IN ('DEPOSIT','WITHDRAW','REG_BUY_SAVE','ADD_BUY_USE','MANUAL_ADJUST','TRANSFER_IN','TRANSFER_OUT')),
 CONSTRAINT "CK_TB_CASH_HIS_03" CHECK("IN_OUT_TP" IN ('IN','OUT')),CONSTRAINT "CK_TB_CASH_HIS_04" CHECK("TX_AMT">0),
 CONSTRAINT "CK_TB_CASH_HIS_05" CHECK("BAL_BFR_AMT">=0),CONSTRAINT "CK_TB_CASH_HIS_06" CHECK("BAL_AFT_AMT">=0));
CREATE INDEX "IDX_TB_CASH_HIS_01" ON "TB_CASH_HIS"("ACCT_ID","TX_DT" DESC); CREATE INDEX "IDX_TB_CASH_HIS_02" ON "TB_CASH_HIS"("REG_BUY_ID"); CREATE INDEX "IDX_TB_CASH_HIS_03" ON "TB_CASH_HIS"("TX_TP","TX_DT" DESC);
COMMENT ON TABLE "TB_CASH_HIS" IS '계좌 일반현금 및 추가매수 대기현금 증감 이력'; COMMENT ON COLUMN "TB_CASH_HIS"."CASH_HIS_ID" IS '현금이력 ID'; COMMENT ON COLUMN "TB_CASH_HIS"."ACCT_ID" IS '계좌 ID'; COMMENT ON COLUMN "TB_CASH_HIS"."REG_BUY_ID" IS '관련 정기매수 설정 ID';
COMMENT ON COLUMN "TB_CASH_HIS"."TX_DT" IS '현금 거래 기준일'; COMMENT ON COLUMN "TB_CASH_HIS"."CASH_TP" IS '현금 유형(NORMAL:일반현금, RESERVE:추가매수 대기현금)'; COMMENT ON COLUMN "TB_CASH_HIS"."TX_TP" IS '현금 거래 유형'; COMMENT ON COLUMN "TB_CASH_HIS"."IN_OUT_TP" IS '현금 증감 유형(IN:증가, OUT:감소)';
COMMENT ON COLUMN "TB_CASH_HIS"."TX_AMT" IS '현금 거래금액'; COMMENT ON COLUMN "TB_CASH_HIS"."BAL_BFR_AMT" IS '거래 전 잔액'; COMMENT ON COLUMN "TB_CASH_HIS"."BAL_AFT_AMT" IS '거래 후 잔액'; COMMENT ON COLUMN "TB_CASH_HIS"."IDEMP_KEY" IS '중복 거래 방지를 위한 멱등성 키';
COMMENT ON COLUMN "TB_CASH_HIS"."REF_TBL_NM" IS '관련 업무 참조 테이블명'; COMMENT ON COLUMN "TB_CASH_HIS"."REF_ID" IS '관련 업무 참조 ID'; COMMENT ON COLUMN "TB_CASH_HIS"."TX_RSN" IS '현금 거래 사유'; COMMENT ON COLUMN "TB_CASH_HIS"."CRT_DTTM" IS '생성일시'; COMMENT ON COLUMN "TB_CASH_HIS"."CRT_USR_ID" IS '생성자 ID';

